const rows = (context.panel.data.series || []).find((s) => s.refId === 'A');
const column = (name) => {
  const f = rows && rows.fields.find((x) => x.name === name);
  if (!f) { return null; }
  return f.values.toArray ? f.values.toArray() : f.values;
};
const clients = column('Client');
const hosts = column('Host');
if (!clients || !hosts) { return []; }
const chosen = context.panel.elements.find((e) => e.id === 'client');
return hosts
  .map((h, i) => ({ host: h, client: clients[i] }))
  .filter((r) => !chosen || !chosen.value || r.client === chosen.value)
  .map((r) => ({ value: r.host, label: r.host }));

update.getPayload:
const v = {};
context.panel.elements.forEach((e) => { v[e.id] = e.value; });
// One item per line in the box, comma-separated on the way out.
const list = (s) => (s || '').split('\n').map((x) => x.trim()).filter((x) => x.length).join(',');
return {
  client: v.client,
  host: v.host,
  name: v.name,
  cron: v.cron,
  machine: v.machine ? 'true' : 'false',
  paths: list(v.paths),
  volumes: list(v.volumes),
  databases: list(v.databases),
  keep_daily: Number(v.keep_daily) || 0,
  keep_weekly: Number(v.keep_weekly) || 0,
  keep_monthly: Number(v.keep_monthly) || 0,
};

